# Loop node functions (encapsulated generate→critic→revise) — generated by graphical-agents from the Graph IR (critic_loop_workflow).

from langchain.agents import create_agent
from langchain.chat_models import init_chat_model

try:
    from .agent_tools import check_python_syntax, run_tool_agent
except ImportError:
    from agent_tools import check_python_syntax, run_tool_agent
try:
    from .schemas import Files, code_loop_CriticOutput
except ImportError:
    from schemas import Files, code_loop_CriticOutput
try:
    from .state import WorkflowState
except ImportError:
    from state import WorkflowState

CODE_LOOP_GENERATOR_INSTRUCTION = (
    "You are an expert developer. Generate code based on the provided specifications."
)
CODE_LOOP_CRITIC_INSTRUCTION = "Review the code against the specifications. Before judging, call the check_python_syntax tool on the content of every Python file; any file that does not return 'OK' must be rejected, quoting the error in your feedback. If every file parses and meets all requirements, return status 'APPROVED'. Otherwise, return detailed feedback."
CODE_LOOP_REVISER_INSTRUCTION = "Fix the provided code based on the critic feedback. After fixing, call the check_python_syntax tool on every Python file and keep fixing until each one returns 'OK'."


def code_loop(state: WorkflowState) -> dict:
    """Generate code, then loop critic+reviser until the critic approves."""
    specifications = state["workflow_input"]
    generator = init_chat_model("google_genai:gemini-flash-latest")
    critic = create_agent(
        init_chat_model("google_genai:gemini-flash-latest"),
        tools=[check_python_syntax],
        response_format=code_loop_CriticOutput,
    )
    reviser = create_agent(
        init_chat_model("google_genai:gemini-flash-latest"),
        tools=[check_python_syntax],
        response_format=Files,
    )
    current = generator.with_structured_output(Files).invoke(
        f"{CODE_LOOP_GENERATOR_INSTRUCTION}\n\nSpecifications:\n{specifications}",
    )
    for _ in range(5):
        crit = run_tool_agent(
            critic,
            f"{CODE_LOOP_CRITIC_INSTRUCTION}\n\nCurrent:\n{current.model_dump_json()}\n\nSpecifications:\n{specifications}",
        )
        if crit.status == "APPROVED":
            return {"code_loop_output": current}
        current = run_tool_agent(
            reviser,
            f"{CODE_LOOP_REVISER_INSTRUCTION}\n\nCritic feedback:\n{crit.feedback}\n\nCurrent:\n{current.model_dump_json()}",
        )
    raise RuntimeError("code_loop failed to produce valid output after 5 rounds")
